/* Calculateur — économie d'un mandat / impact des frais */
(function () {
  function lang(){ return document.body.getAttribute("data-active-lang") || "fr"; }
  function locale(){ var l=lang(); return l==="en" ? "en-US" : (l==="nl" ? "nl-BE" : "fr-FR"); }
  function money(x){ return new Intl.NumberFormat(locale(), {style:"currency", currency:"EUR", maximumFractionDigits:0}).format(x); }
  function pct(x){ return (x*100).toFixed(2).replace(".", lang()==="en" ? "." : ",") + "%"; }
  function $(id){ return document.getElementById(id); }

  function compute(){
    var V   = parseFloat($("c-cap").value) || 0;
    var fee = parseFloat($("c-fee").value)/10000;
    var gr  = parseFloat($("c-ret").value)/100;
    var N   = parseInt($("c-yrs").value,10);

    $("c-fee-out").textContent = $("c-fee").value + " bps";
    $("c-ret-out").textContent = $("c-ret").value + "%";
    $("c-yrs-out").textContent = N;

    var value = V, feesPaid = 0;
    for (var i=0;i<N;i++){
      var gross = value*(1+gr);
      var feeAmt = gross*fee;
      value = gross - feeAmt;
      feesPaid += feeAmt;
    }
    var FVn = value;
    var FVg = V*Math.pow(1+gr, N);
    var drag = FVg - FVn;
    var netAnn = N>0 ? Math.pow(FVn/V, 1/N)-1 : 0;

    $("r-net").textContent  = money(FVn);
    $("r-netann").textContent = (lang()==="en"?"Net annualised: ":(lang()==="nl"?"Netto geannualiseerd: ":"Rendement net annualisé : ")) + pct(netAnn);
    $("r-fees").textContent = money(feesPaid);
    $("r-drag").textContent = (lang()==="en"?"Shortfall vs no fees: ":(lang()==="nl"?"Manco vs zonder kosten: ":"Manque à gagner vs sans frais : ")) + money(drag);
    var grossLbl = lang()==="en"?"Gross value (no fees): ":(lang()==="nl"?"Brutowaarde (zonder kosten): ":"Valeur brute (sans frais) : ");
    $("r-detail").textContent = grossLbl + money(FVg);
  }

  ["c-cap","c-fee","c-ret","c-yrs"].forEach(function(id){
    var el = document.getElementById(id);
    if (el){ el.addEventListener("input", compute); }
  });
  document.querySelectorAll(".lang-toggle button").forEach(function(b){
    b.addEventListener("click", function(){ setTimeout(compute, 0); });
  });
  document.addEventListener("DOMContentLoaded", compute);
  compute();
})();
